#!/bin/sh
# Generates src/Blokky.Core/Syntax/SimpleCase.Table.g.cs: the Unicode simple uppercase
# mapping (UnicodeData.txt field 12) that CO-12 pins to Unicode 16.0.
#
#   curl -sSfLO https://www.unicode.org/Public/16.0.0/ucd/UnicodeData.txt
#   scripts/gen-simple-case.sh UnicodeData.txt > src/Blokky.Core/Syntax/SimpleCase.Table.g.cs
set -eu

if [ "$#" -ne 1 ] || [ ! -f "$1" ]; then
  echo "usage: $0 path/to/UnicodeData.txt (Unicode 16.0.0)" >&2
  exit 2
fi

printf '%s\n' \
  '// <auto-generated> scripts/gen-simple-case.sh from UnicodeData.txt, Unicode 16.0.0 </auto-generated>' \
  'namespace Blokky.Core.Syntax;' \
  '' \
  'public static partial class SimpleCase' \
  '{' \
  '    /// <summary>Code point, simple uppercase mapping: pairs sorted by code point.</summary>' \
  '    private static ReadOnlySpan<int> Pairs =>' \
  '    ['
awk -F ';' '$13 != "" { printf "        0x%s, 0x%s,\n", $1, $13 }' "$1"
printf '%s\n' \
  '    ];' \
  '}'
